it("should turn a vertical blinker into a horizontal blinker", () => {
  expect(
    sorted(
      nextGeneration([
        [0, 0],
        [0, 1],
        [0, 2],
      ]),
    ),
  ).toEqual(
    sorted([
      [-1, 1],
      [0, 1],
      [1, 1],
    ]),
  );
});

import { nextGeneration, type Cell } from "./game-of-life.js";

const sorted = (cells: Cell[]): Cell[] =>
  [...cells].sort(([ax, ay], [bx, by]) => ax - bx || ay - by);
